function cents(value){return value===null?'':(Math.floor(value/100)+','+String(value%100).padStart(2,'0'));}
function parseCents(value){if(!/^\d+(?:[.,]\d{1,2})?$/.test(value))throw new Error(t('invalidMoney'));const [whole,fraction='']=value.replace(',','.').split('.');const amount=Number(whole)*100+Number(fraction.padEnd(2,'0'));if(!Number.isSafeInteger(amount)||amount>999999999)throw new Error(t('invalidMoney'));return amount;}
function editField(parent,key,model,prop,type='text',required=true){const input=field(parent,key,model[prop]??'',type,required);input.oninput=()=>{model[prop]=type==='number'?Number(input.value):input.value;};return input;}
