let pinLoginCleanup=()=>{};
function clearPinCard(){pinLoginCleanup();pinLoginCleanup=()=>{};}
function login(){
 if(serverSchema<6){passwordLogin();return;}
 clearPinCard();const section=shell(t('cashierLogin'),true);section.classList.add('cashier-login','auth-screen');section.append(el('p',t('pinHint')));
 const input=el('input',undefined,{type:'password',maxLength:4,autocomplete:'off',className:'pin-input'});input.setAttribute('aria-label','PIN');input.inputMode='numeric';const entry=el('div',undefined,{className:'pin-entry'}),cells=Array.from({length:4},()=>el('span',undefined,{className:'pin-cell'}));cells.forEach(cell=>{cell.setAttribute('aria-hidden','true');entry.append(cell);});entry.append(input);section.append(entry);const draw=()=>cells.forEach((cell,i)=>cell.textContent=i<input.value.length?'\u2022':'');
 const keypad=el('div',undefined,{className:'pin-keypad'}),note=el('p',undefined,{role:'status'});let busy=false,retryAt=0,active=true;
 const controls=[];const attempt=async()=>{if(busy||Date.now()<retryAt||input.value.length!==4)return;busy=true;input.disabled=true;controls.forEach(b=>b.disabled=true);const value=input.value;input.value='';draw();
 try{await api('pinLogin',{pin:value});if(!active)return;me=await api('me');screen=posSalesHome(me);await render();}
 catch(error){if(!active)return;retryAt=Date.now()+(error.retryAfterSeconds??(error.message==='PIN_WORK_LIMIT'?1:0))*1000;note.textContent=['INVALID_CREDENTIALS','PIN_RATE_LIMITED','PIN_WORK_LIMIT'].includes(error.message)?t('pinDenied'):(domainMessages[error.message]?.[lang==='ky'?1:0]??t('connection'));}
 finally{busy=false;if(active){input.disabled=Date.now()<retryAt;controls.forEach(b=>b.disabled=input.disabled);input.focus();}}};
 for(const digit of ['1','2','3','4','5','6','7','8','9','0']){const b=el('button',digit,{type:'button'});b.onclick=()=>{if(!busy&&Date.now()>=retryAt){input.value=(input.value+digit).slice(0,4);draw();attempt();}};controls.push(b);keypad.append(b);}
 const remove=button(keypad,'pinDelete',()=>{input.value=input.value.slice(0,-1);draw();});remove.classList.add('pin-delete');remove.textContent='⌫';remove.setAttribute('aria-label',t('pinDelete'));controls.push(remove);
 const enter=button(keypad,'enter',attempt,true);enter.classList.add('pin-submit');enter.textContent='→';enter.setAttribute('aria-label',t('enter'));controls.push(enter);
 input.oninput=()=>{input.value=input.value.replace(/[^0-9]/g,'').slice(0,4);draw();attempt();};section.append(keypad,note);
 const actions=el('div',undefined,{className:'auth-actions'});button(actions,'passwordLogin',passwordLogin);button(actions,'ownerDashboard',ownerLogin);section.append(actions);
 const timer=setInterval(()=>{if(!active)return;const remaining=Math.ceil((retryAt-Date.now())/1000);if(remaining>0)note.textContent=`${t('pinWait')} ${remaining} ${t('pinSeconds')}`;if(remaining<=0&&retryAt){retryAt=0;note.textContent=t('pinHint');}if(!busy){input.disabled=remaining>0;controls.forEach(b=>b.disabled=remaining>0);}},250);
 pinLoginCleanup=()=>{active=false;input.value='';clearInterval(timer);};input.focus();
}
labels();run(boot);
